  const enriched=rows.map(line=>{const used=transactions.filter(t=>t.type==="STOCK OUT"&&t.site===line.site&&t.code===line.code&&t.costCode===line.costCode).reduce((a,t)=>a+Math.abs(t.qty),0);return {...line,used,balance:line.approvedQty-used,utilization:Math.round(used/Math.max(line.approvedQty,0.0001)*100)};});
